//! Writes the Rust token modules.
//!
//! The output is formatted the way `rustfmt` formats it, so `cargo fmt --check` and the generator's own check agree.

use std::fmt::Write as _;

use std::collections::BTreeSet;

use crate::kotlin::{TokenObject, Value};

/// `rustfmt`'s default `max_width`.
const MAX_WIDTH: usize = 100;

/// The first line of every generated file.
pub(crate) const GENERATED_MARKER: &str = "// @generated by `cargo xtask gen-tokens`.";

/// The Rust module for one token file.
///
/// `file` is the vendored file's name and `doc` the module's documentation, one paragraph per element.
pub(crate) fn module(object: &TokenObject, file: &str, doc: &[&str]) -> String {
    let mut out = String::new();
    out.push_str(GENERATED_MARKER);
    out.push('\n');
    let version = object
        .version
        .as_deref()
        .map(|version| format!(" (token version {version})"))
        .unwrap_or_default();
    let _ = writeln!(
        out,
        "// Source: `reference/androidx-material3-tokens/{file}`{version}."
    );
    out.push_str(
        "// Do not edit by hand: change the vendored file or the generator, then run it again.\n\n",
    );
    let _ = writeln!(out, "//! androidx `{}`.", object.name);
    for paragraph in doc {
        out.push_str("//!\n");
        push_doc(&mut out, paragraph);
    }
    let imports = imports(object);
    if !imports.is_empty() {
        out.push('\n');
        for import in imports {
            let _ = writeln!(out, "use {import};");
        }
    }
    for token in &object.tokens {
        let (ty, expression, alias) = match &token.value {
            Value::Number(number) => ("f32", literal(*number), String::new()),
            Value::CubicBezier([x1, y1, x2, y2]) => (
                "CubicBezier",
                format!(
                    "CubicBezier::new({}, {}, {}, {})",
                    literal(*x1),
                    literal(*y1),
                    literal(*x2),
                    literal(*y2)
                ),
                String::new(),
            ),
            Value::Srgb([red, green, blue]) => (
                "Srgb",
                format!("Srgb::new({red}, {green}, {blue})"),
                String::new(),
            ),
            Value::Color(reference) => (
                "Srgb",
                if reference.object == object.name {
                    screaming_snake(&reference.token)
                } else {
                    format!(
                        "{}::{}",
                        snake(&reference.object),
                        screaming_snake(&reference.token)
                    )
                },
                format!(" = `{}.{}`", reference.object, reference.token),
            ),
        };
        let _ = writeln!(
            out,
            "\n/// androidx: `{}.{}`{alias}.",
            object.name, token.name
        );
        let head = format!("pub const {}: {ty} =", screaming_snake(&token.name));
        let one_line_width = head.len() + " ".len() + expression.len() + ";".len();
        if one_line_width <= MAX_WIDTH {
            let _ = writeln!(out, "{head} {expression};");
        } else {
            let _ = writeln!(out, "{head}\n    {expression};");
        }
    }
    out
}

/// The `use` paths a module needs, in the order `rustfmt` sorts them: `super::` before `crate::`.
fn imports(object: &TokenObject) -> Vec<String> {
    let mut types = BTreeSet::new();
    let mut modules = BTreeSet::new();
    for token in &object.tokens {
        match &token.value {
            Value::Number(_) => {}
            Value::CubicBezier(_) => {
                types.insert("CubicBezier");
            }
            Value::Srgb(_) => {
                types.insert("Srgb");
            }
            Value::Color(reference) => {
                types.insert("Srgb");
                if reference.object != object.name {
                    modules.insert(snake(&reference.object));
                }
            }
        }
    }
    let mut imports: Vec<String> = modules
        .into_iter()
        .map(|module| format!("super::{module}"))
        .collect();
    let types: Vec<&str> = types.into_iter().collect();
    match types.as_slice() {
        [] => {}
        [one] => imports.push(format!("crate::tokens::{one}")),
        many => imports.push(format!("crate::tokens::{{{}}}", many.join(", "))),
    }
    imports
}

/// The `mod.rs` that declares the generated modules, sorted as `rustfmt` sorts them.
pub(crate) fn index(modules: &[String], doc: &[&str]) -> String {
    let mut out = String::new();
    out.push_str(GENERATED_MARKER);
    out.push('\n');
    out.push_str("// Do not edit by hand: change the generator, then run it again.\n\n");
    for (index, paragraph) in doc.iter().enumerate() {
        if index > 0 {
            out.push_str("//!\n");
        }
        push_doc(&mut out, paragraph);
    }
    out.push('\n');
    let mut sorted = modules.to_vec();
    sorted.sort();
    for module in sorted {
        let _ = writeln!(out, "pub mod {module};");
    }
    out
}

/// One paragraph of `//!` documentation, wrapped at [`MAX_WIDTH`] between words.
fn push_doc(out: &mut String, paragraph: &str) {
    const PREFIX: &str = "//!";
    let mut line = String::from(PREFIX);
    for word in paragraph.split_whitespace() {
        if line.len() > PREFIX.len() && line.len() + 1 + word.len() > MAX_WIDTH {
            out.push_str(&line);
            out.push('\n');
            line = String::from(PREFIX);
        }
        line.push(' ');
        line.push_str(word);
    }
    out.push_str(&line);
    out.push('\n');
}

/// The shortest literal that reads back as the same `f32`, always with a fraction (`700.0`, `0.8`).
fn literal(number: f32) -> String {
    format!("{number:?}")
}

/// `DurationExtraLong1` → `DURATION_EXTRA_LONG1`.
pub(crate) fn screaming_snake(name: &str) -> String {
    convert(name, true)
}

/// `ExpressiveMotionTokens` → `expressive_motion_tokens`.
pub(crate) fn snake(name: &str) -> String {
    convert(name, false)
}

fn convert(name: &str, upper: bool) -> String {
    let mut out = String::with_capacity(name.len() + 4);
    let mut previous: Option<char> = None;
    for c in name.chars() {
        let after_word = previous.is_some_and(|p| p.is_ascii_lowercase() || p.is_ascii_digit());
        if c.is_ascii_uppercase() && after_word {
            out.push('_');
        }
        out.push(if upper {
            c.to_ascii_uppercase()
        } else {
            c.to_ascii_lowercase()
        });
        previous = Some(c);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::kotlin::{Reference, Token};

    fn color(name: &str, object: &str, token: &str) -> Token {
        Token {
            name: name.into(),
            value: Value::Color(Reference {
                object: object.into(),
                token: token.into(),
            }),
        }
    }

    #[test]
    fn converts_names_at_word_boundaries_only() {
        assert_eq!(
            screaming_snake("DurationExtraLong1"),
            "DURATION_EXTRA_LONG1"
        );
        assert_eq!(
            screaming_snake("EasingEmphasizedCubicBezier"),
            "EASING_EMPHASIZED_CUBIC_BEZIER"
        );
        assert_eq!(screaming_snake("ButtonXLarge"), "BUTTON_XLARGE");
        assert_eq!(screaming_snake("Level3Shadow"), "LEVEL3_SHADOW");
        assert_eq!(snake("ExpressiveMotionTokens"), "expressive_motion_tokens");
        assert_eq!(snake("MotionTokens"), "motion_tokens");
    }

    #[test]
    fn literals_read_back_as_the_same_f32() {
        for number in [700.0_f32, 0.8, 0.15, 0.05, 3800.0, -0.25] {
            let text = literal(number);
            assert!(text.contains('.'), "{text} has no fraction");
            assert_eq!(text.parse::<f32>().unwrap().to_bits(), number.to_bits());
        }
    }

    fn sample(tokens: Vec<Token>) -> TokenObject {
        TokenObject {
            name: "SampleTokens".into(),
            version: Some("v0_1".into()),
            tokens,
        }
    }

    #[test]
    fn writes_a_documented_constant_per_token() {
        let object = sample(vec![Token {
            name: "DurationShort1".into(),
            value: Value::Number(50.0),
        }]);
        let out = module(&object, "SampleTokens.kt", &["Durations."]);
        assert!(out.starts_with(GENERATED_MARKER));
        assert!(out.contains(
            "`reference/androidx-material3-tokens/SampleTokens.kt` (token version v0_1)"
        ));
        assert!(out.contains("//! androidx `SampleTokens`.\n//!\n//! Durations.\n"));
        assert!(out.contains(
            "\n/// androidx: `SampleTokens.DurationShort1`.\npub const DURATION_SHORT1: f32 = 50.0;\n"
        ));
        assert!(!out.contains("use crate::tokens::CubicBezier;"));
    }

    #[test]
    fn imports_the_curve_type_and_wraps_long_lines_like_rustfmt() {
        let object = sample(vec![
            Token {
                name: "EasingEmphasizedAccelerateCubicBezier".into(),
                value: Value::CubicBezier([0.3, 0.0, 0.8, 0.15]),
            },
            Token {
                name: "Linear".into(),
                value: Value::CubicBezier([0.0, 0.0, 1.0, 1.0]),
            },
        ]);
        let out = module(&object, "SampleTokens.kt", &[]);
        assert!(out.contains("\nuse crate::tokens::CubicBezier;\n"));
        assert!(out.contains(
            "pub const EASING_EMPHASIZED_ACCELERATE_CUBIC_BEZIER: CubicBezier =\n    CubicBezier::new(0.3, 0.0, 0.8, 0.15);\n"
        ));
        assert!(
            out.contains("pub const LINEAR: CubicBezier = CubicBezier::new(0.0, 0.0, 1.0, 1.0);\n")
        );
        assert!(out.lines().all(|line| line.len() <= MAX_WIDTH));
    }

    #[test]
    fn the_index_lists_modules_sorted() {
        let out = index(
            &["motion_tokens".into(), "expressive_motion_tokens".into()],
            &["Tokens."],
        );
        assert!(out.ends_with("pub mod expressive_motion_tokens;\npub mod motion_tokens;\n"));
    }

    #[test]
    fn a_constant_of_exactly_the_width_stays_on_one_line() {
        // `pub const ` + name + `: f32 = 1.0;` is the name's length plus 22.
        let constant = |name_len: usize| {
            let name = format!("A{}", "a".repeat(name_len - 1));
            let object = sample(vec![Token {
                name,
                value: Value::Number(1.0),
            }]);
            let out = module(&object, "SampleTokens.kt", &[]);
            out.lines()
                .skip_while(|line| !line.starts_with("pub const"))
                .map(str::to_owned)
                .collect::<Vec<_>>()
        };
        let fits = constant(MAX_WIDTH - 22);
        assert_eq!(fits.len(), 1);
        assert_eq!(fits[0].len(), MAX_WIDTH);
        let wraps = constant(MAX_WIDTH - 21);
        assert_eq!(wraps.len(), 2);
        assert!(wraps[0].ends_with(": f32 =") && wraps[1] == "    1.0;");
    }

    #[test]
    fn the_index_separates_its_paragraphs_once() {
        let out = index(&[], &["First.", "Second."]);
        assert!(
            out.contains("run it again.\n\n//! First.\n//!\n//! Second.\n\n"),
            "{out}"
        );
    }

    #[test]
    fn a_doc_line_of_exactly_the_width_is_not_wrapped() {
        // `//! ` + 94 letters + ` y` is 100 characters.
        let mut out = String::new();
        push_doc(&mut out, &format!("{} y", "x".repeat(94)));
        assert_eq!(out.lines().count(), 1);
        let mut out = String::new();
        push_doc(&mut out, &format!("{} y", "x".repeat(95)));
        assert_eq!(
            out.lines().collect::<Vec<_>>(),
            [format!("//! {}", "x".repeat(95)).as_str(), "//! y"]
        );
    }

    #[test]
    fn a_word_longer_than_the_width_gets_its_own_line_and_no_empty_one() {
        let long = "z".repeat(MAX_WIDTH + 10);
        let mut out = String::new();
        push_doc(&mut out, &format!("{long} end"));
        assert_eq!(out, format!("//! {long}\n//! end\n"));
    }

    #[test]
    fn wraps_documentation_between_words_within_the_width() {
        let words = ["word"; 60].join(" ");
        let mut out = String::new();
        push_doc(&mut out, &words);
        assert!(out.lines().count() > 1);
        assert!(
            out.lines()
                .all(|line| line.len() <= MAX_WIDTH && line.starts_with("//! word"))
        );
        let rejoined: Vec<&str> = out
            .lines()
            .flat_map(|line| line.split_whitespace().skip(1))
            .collect();
        assert_eq!(rejoined.join(" "), words);
    }

    #[test]
    fn writes_colors_and_references_with_their_imports() {
        let object = sample(vec![
            Token {
                name: "Neutral98".into(),
                value: Value::Srgb([254, 247, 0]),
            },
            color("Background", "PaletteTokens", "Neutral98"),
            color("SurfaceTint", "SampleTokens", "Neutral98"),
            color("Error", "OtherPaletteTokens", "Error40"),
        ]);
        let out = module(&object, "SampleTokens.kt", &[]);
        assert!(
            out.contains(
                "\nuse super::other_palette_tokens;\nuse super::palette_tokens;\nuse crate::tokens::Srgb;\n\n"
            ),
            "{out}"
        );
        assert!(out.contains(
            "\n/// androidx: `SampleTokens.Neutral98`.\npub const NEUTRAL98: Srgb = Srgb::new(254, 247, 0);\n"
        ));
        assert!(out.contains(
            "\n/// androidx: `SampleTokens.Background` = `PaletteTokens.Neutral98`.\npub const BACKGROUND: Srgb = palette_tokens::NEUTRAL98;\n"
        ));
        // A token of the same object is named directly, and its module is not imported into itself.
        assert!(out.contains(
            "\n/// androidx: `SampleTokens.SurfaceTint` = `SampleTokens.Neutral98`.\npub const SURFACE_TINT: Srgb = NEUTRAL98;\n"
        ));
        assert!(!out.contains("use super::sample_tokens;"));
        assert!(out.contains("pub const ERROR: Srgb = other_palette_tokens::ERROR40;\n"));
    }

    #[test]
    fn imports_nothing_for_numbers_and_only_what_is_used() {
        let numbers = sample(vec![Token {
            name: "A".into(),
            value: Value::Number(1.0),
        }]);
        assert_eq!(imports(&numbers), Vec::<String>::new());
        assert!(!module(&numbers, "SampleTokens.kt", &[]).contains("\nuse "));

        let srgb = sample(vec![Token {
            name: "A".into(),
            value: Value::Srgb([0, 0, 0]),
        }]);
        assert_eq!(imports(&srgb), ["crate::tokens::Srgb"]);

        let own = sample(vec![color("A", "SampleTokens", "B")]);
        assert_eq!(imports(&own), ["crate::tokens::Srgb"]);

        let both = sample(vec![
            Token {
                name: "A".into(),
                value: Value::Srgb([0, 0, 0]),
            },
            Token {
                name: "B".into(),
                value: Value::CubicBezier([0.0, 0.0, 1.0, 1.0]),
            },
        ]);
        assert_eq!(imports(&both), ["crate::tokens::{CubicBezier, Srgb}"]);
    }
}
